const alert = $input.first().json.body;
const ruleId = alert.rule?.id || '';
const srcIp = alert.data?.srcip || 'unknown';

// Determine alert type
let alertType = 'unknown';
if (['100530', '100531', '100532'].includes(ruleId)) alertType = 'dns_tunneling';
if (['100525', '100526', '100527'].includes(ruleId)) alertType = 'dga';
if (['100535', '100536'].includes(ruleId)) alertType = 'dns_flood';

return [{
  json: {
    alert_type: alertType,
    source_ip: srcIp,
    rule_id: ruleId,
    query: alert.data?.query || '',
    timestamp: new Date().toISOString(),
    raw_alert: alert
  }
}];

const dnsAlert = $('Classify DNS Alert').first().json;
const ja3Alerts = $input.first().json;

const hasJA3Match = Array.isArray(ja3Alerts) && ja3Alerts.length > 0;

if (hasJA3Match) {
  // Merge into attack chain
  return [{
    json: {
      action: 'MERGE_ATTACK_CHAIN',
      chain_id: `CHAIN-${Date.now()}`,
      title: `Multi-Vector Attack: DNS Abuse + Encrypted Malware from ${dnsAlert.source_ip}`,
      severity: 'CRITICAL',
      confidence: 94,
      source_ip: dnsAlert.source_ip,
      steps: [
        {
          phase: 'DNS Abuse',
          type: dnsAlert.alert_type,
          mitre: 'T1572',
          evidence: `DNS query: ${dnsAlert.query}`
        },
        {
          phase: 'Encrypted C2',
          type: 'ja3_match',
          mitre: 'T1573.002',
          evidence: `Malicious JA3 fingerprint from same source IP`
        }
      ],
      kill_chain_phases: ['Command and Control'],
      timestamp: new Date().toISOString()
    }
  }];
} else {
  return [{
    json: {
      action: 'STANDALONE_ALERT',
      title: `DNS ${dnsAlert.alert_type} from ${dnsAlert.source_ip}`,
      severity: 'HIGH',
      confidence: 72,
      source_ip: dnsAlert.source_ip,
      timestamp: new Date().toISOString()
    }
  }];
}
